import { InteractiveLab } from './components/InteractiveLab.tsx';
import { VanillaLab } from './components/VanillaLab.tsx';

export function App() {
  const params = new URLSearchParams(window.location.search);
  const test = params.get('test');
  const backend = params.get('backend');
  if (test === '14-open-world') return <VanillaLab test="14-open-world" />;
  if (test === '04-gpu-lod' && backend !== 'legacy') return <VanillaLab test="04-gpu-lod" />;
  return <InteractiveLab />;
}

