import { useLayoutEffect, useRef, useState } from 'react';
import { parseMarkdownToHtml } from '../lab/markdown.ts';
import { initialSnapshot, type LabActions, type LabSnapshot } from '../lab/labState.ts';
import { LabContext } from './LabContext.tsx';
import { LabShell } from './LabShell.tsx';

type VanillaLabProps = {
  test: '04-gpu-lod' | '14-open-world';
};

export function navigateFromNativeBench(moduleId: string): void {
  window.history.pushState({}, '', `/?test=${encodeURIComponent(moduleId)}`);
  window.location.reload();
}

const idleActions: LabActions = {
  switchModule: (moduleId) => {
    navigateFromNativeBench(moduleId);
  },
  setMode: () => undefined,
  setScenario: () => undefined,
  runBenchmark: () => undefined,
  runPain: () => undefined,
  openReport: () => undefined,
  closeReport: () => undefined,
  copyReport: () => undefined,
  refreshReport: () => undefined,
  openFinder: () => undefined,
};

export function VanillaLab({ test }: VanillaLabProps) {
  const webglRef = useRef<HTMLCanvasElement>(null);
  const webgpuRef = useRef<HTMLCanvasElement>(null);
  const chartRef = useRef<HTMLCanvasElement>(null);
  const [state, setState] = useState<LabSnapshot>(() => ({
    ...initialSnapshot(test),
    moduleId: test,
    showBaseline: false,
    showWebgl: test === '14-open-world',
    showWebgpu: test === '04-gpu-lod',
    showChart: test === '04-gpu-lod',
    showPain: true,
    running: true,
    execution: { status: 'running', phase: 'Initialisation du banc…', lastCampaign: null },
  }));

  const [actions, setActions] = useState<LabActions>(() => idleActions);

  useLayoutEffect(() => {
    let cancelled = false;
    let dispose: (() => void) | undefined;
    void (async () => {
      if (cancelled) return;
      if (test === '14-open-world') {
        const { mountWorldWorkbench } = await import('../../14-open-world/worldPage.ts');
        const controller = mountWorldWorkbench(patch => { if (!cancelled) setState(previous => ({ ...previous, ...patch })); });
        if (cancelled) {
          controller.dispose();
          return;
        }
        dispose = controller.dispose;
        setActions({ ...idleActions, setMode: controller.setMode, runBenchmark: controller.run, runPain: controller.stop, stopBenchmark: controller.stop, openReport: controller.report });
        setState(previous => ({ ...previous, running: false, execution: { status: 'idle', phase: '', lastCampaign: null } }));
        return;
      }
      const { mountNativeLodWorkbench } = await import('../../04-gpu-lod/benchmark/nativePage.ts');
      const controller = mountNativeLodWorkbench(parseMarkdownToHtml, patch => { if (!cancelled) setState(previous => ({ ...previous, ...patch })); });
      if (cancelled) {
        controller.dispose();
        return;
      }
      dispose = controller.dispose;
      setActions({ ...idleActions, setMode: controller.setMode, runBenchmark: controller.run, runPain: controller.stop, stopBenchmark: controller.stop, openReport: controller.report });
      setState(previous => ({ ...previous, running: false, execution: { status: 'idle', phase: '', lastCampaign: null } }));
    })();
    return () => {
      cancelled = true;
      dispose?.();
    };
  }, [test]);

  return (
    <LabContext.Provider value={{ state, actions }}>
      <LabShell webglRef={webglRef} webgpuRef={webgpuRef} chartRef={chartRef} />
    </LabContext.Provider>
  );
}

