import type { RefObject } from 'react';

type ViewportCanvasesProps = {
  webglRef: RefObject<HTMLCanvasElement | null>;
  webgpuRef: RefObject<HTMLCanvasElement | null>;
  showWebgl: boolean;
  showWebgpu: boolean;
};

export function ViewportCanvases({ webglRef, webgpuRef, showWebgl, showWebgpu }: ViewportCanvasesProps) {
  return (
    <>
      <canvas
        id="canvas-webgl"
        ref={webglRef}
        className="absolute inset-0 w-full h-full block"
        style={{ display: showWebgl ? 'block' : 'none', objectFit: 'cover' }}
      />
      <canvas
        id="canvas-webgpu"
        ref={webgpuRef}
        className="absolute inset-0 w-full h-full block"
        style={{ display: showWebgpu ? 'block' : 'none', objectFit: 'cover' }}
      />
    </>
  );
}

