          cpuRenderSubmitMs:rendered-renderStart,cpuFrameWorkMs:performance.now()-begin,gpuMs:null,...counts()};
        block.samples.push(sample);allSamples.push(sample);if(query)queries.push({query,sample});previous=raf;
        onMetrics?.({...sample,gpuMs:lastGpuMs,gpuTimerAvailable:!!timer,variant,phase:'measure',sourceTriangles:sourceTrianglesPerDistrict*config.districts,sourceMeshes:sourceMeshesPerDistrict*config.districts});
        if(index%30===29||index===config.samples-1)emit({phase:'measurement',message:`Bloc ${blockIndex+1}/4 : ${index+1}/${config.samples} images mesurées.`,completed:index+1,total:config.samples,unit:'frames'});
      }
      blocks.push(block);
    }
    emit({phase:'gpu-drain',message:'Collecte non bloquante des dernières durées GPU.',completed:0,total:queries.length,unit:'frames'});
    for(let i=0;i<120&&queries.length;i++){await nextFrame();check();poll();if(i%15===14||!queries.length)emit({phase:'gpu-drain',message:`Collecte GPU : ${queries.length} requête(s) restante(s).`,completed:i+1,total:120,unit:'frames'});}
    for(const block of blocks)block.summary=Object.fromEntries((['cpuCullMs','cpuRenderSubmitMs','cpuFrameWorkMs','rafDeltaMs','gpuMs','mainPassTriangles','shadowPassTriangles','mainPassDrawCalls','shadowPassDrawCalls','lines','mainPassLines','shadowPassLines','activeDistricts'] as const).map(key=>[key,summary(block.samples.map(s=>s[key]))]));
    const result=report(true);result.qualityMs=qualityMs;result.environment.gpuDisjointEvents=gpuDisjointEvents;result.environment.gpuUnresolvedQueries=queries.length;
    emit({phase:'complete',message:'Mesures terminées ; résultat prêt à archiver.',completed:4,total:4,unit:'blocks'});return result;
  } catch(error) {
    if(signal?.aborted)onLifecycle?.({phase:'cancelled',message:'Exécution annulée ; dernière image valide conservée.'});
    throw error;
  } finally {if(!ownsPreview)cleanup();}
}
export async function runWorldComparison(canvas:HTMLCanvasElement,options:WorldOptions,onProgress:(message:string)=>void=()=>{},signal?:AbortSignal,onMetrics?:(metrics:WorldPreviewMetrics)=>void,onLifecycle?:(progress:WorldProgress)=>void):Promise<WorldReport>{
  return await execute(canvas,options,onProgress,signal,undefined,undefined,onMetrics,onLifecycle) as WorldReport;
}
export async function startWorldPreview(canvas:HTMLCanvasElement,options:WorldOptions,onFrame:(metrics:WorldPreviewMetrics)=>void=()=>{},signal?:AbortSignal,onError?:(error:Error)=>void,onComplete?:(completion:WorldPreviewCompletion)=>void,onLifecycle?:(progress:WorldProgress)=>void):Promise<()=>void>{
  return await execute(canvas,options,()=>{},signal,onFrame,onError,undefined,onLifecycle,onComplete) as ()=>void;
}

