    field('world-fov', 'Angle de vue', [['45', '45°'], ['60', '60°'], ['90', '90°']], '60'),
    field('world-path', 'Parcours', [['mixed', 'Mixte'], ['perimeter', 'Périmètre au sol'], ['panorama', 'Panorama']], 'mixed'),
